例の入力:{"fields":[{"field":1,"text":"頼まれた仕事を断りたかった。相手が困ったかは知らない。"}]}
例の出力:{"fields":[{"field":1,"units":[{"quote":"断りたかった","scope_role":null,"node_kind":"ATTENTION_OR_THOUGHT","parent":null,"qualifiers":[]},{"quote":"頼まれた仕事","scope_role":"CONTENT_TARGET","node_kind":null,"parent":1,"qualifiers":[]},{"quote":"知らない","scope_role":"WRITTEN_UNKNOWN","node_kind":null,"parent":null,"qualifiers":[{"quote":"知らない","kind":"EPISTEMIC_EXPRESSION"}]},{"quote":"相手が困ったか","scope_role":"UNKNOWN_CONTENT","node_kind":null,"parent":3,"qualifiers":[]}]}]}
