例の出力:{"fields":[{"field":1,"units":[{"quote":"行かなかった","scope_role":null,"node_kind":"ACTION_OR_NONACTION","parent":null,"qualifiers":[{"quote":"なかった","kind":"NEGATION"}]},{"quote":"会合","scope_role":"CONTENT_TARGET","node_kind":null,"parent":1,"qualifiers":[]},{"quote":"眠かったので","scope_role":"WRITTEN_REASON","node_kind":null,"parent":1,"qualifiers":[{"quote":"ので","kind":"REASON_MARKER"}]}]}]}
